const venus='https://science.nasa.gov/venus/venus-facts/',saturn='https://science.nasa.gov/saturn/facts/',jupiter='https://science.nasa.gov/jupiter/jupiter-facts/',neptune='https://science.nasa.gov/neptune/neptune-facts/';
const facts=[
 ['金星转一圈，比过一年还久','金星自转一周约需 243 个地球日，绕太阳一周却只需约 225 个地球日。这里比较的是自转周期，并非两次日出之间的时间。',venus,'NASA · 金星','宇宙'],
 ['最热的行星，并不是离太阳最近的','金星比水星离太阳更远，却是太阳系最热的行星。浓厚大气造成强烈温室效应，金星表面温度约为 467°C。',venus,'NASA · 金星','宇宙'],
 ['在金星，太阳从西边升起','金星的自转方向与地球相反，因此从金星表面看，太阳会从西方升起、东方落下。',venus,'NASA · 金星','宇宙'],
 ['土星的平均密度，比水还低','土星是太阳系中唯一平均密度低于水的行星。这是整体平均密度的比较，并不表示真实存在能装下土星的浴缸。',saturn,'NASA · 土星','宇宙'],
 ['土星的一天，只有约 10.7 小时','土星自转一周约需 10.7 小时，绕太阳一周却要约 29.4 个地球年。一天很短，一年很长。',saturn,'NASA · 土星','宇宙'],
 ['土星北极有一个六边形','土星北极存在巨大的六边形大气图案。它是波状喷流形成的结构，并不是坚硬的地形。',saturn,'NASA · 土星','宇宙'],
 ['木星是太阳系最大的行星','木星的直径大约是地球的 11 倍。它是气态巨行星，没有像地球那样可供站立的固体表面。',jupiter,'NASA · 木星','宇宙'],
 ['木星也有光环','光环并不是土星的专利。旅行者 1 号在 1979 年发现了木星的暗淡环系，其主要成分是微小的暗色颗粒。',jupiter,'NASA · 木星','宇宙'],
 ['木星上的一天，不到十小时','木星约 9.9 小时就自转一周，是太阳系自转周期最短的行星。',jupiter,'NASA · 木星','宇宙'],
 ['海王星过一年，地球过了约 165 年','海王星绕太阳一周约需 165 个地球年，而它自转一周约需 16 小时。',neptune,'NASA · 海王星','宇宙'],
 ['地球上的水，大约 97% 在海洋里','海洋覆盖地球表面的 70% 以上，也容纳了地球约 97% 的水。面积占比与水量占比是两个不同的数字。','https://oceanservice.noaa.gov/facts/oceanwater.html','NOAA · 海洋水量','自然'],
 ['章鱼有三颗心脏','章鱼有两颗心脏负责把血液泵向鳃，另一颗心脏把含氧血液送往身体其他部位。','https://oceanservice.noaa.gov/news/feb26/undersea-creatures-valentines-day.html','NOAA · 海洋动物','自然']
].map(([title,body,url,source,tag],i)=>({id:`f${i+1}`,type:'fact',title,body,url,source,tags:[tag,'冷知识'],verified:'2026-10-17'}));
export const content=[...jokes,...facts];
